    val MAP: Map<String, DuaText> = mapOf(
        "dua_rahmataka_arju" to DuaText("আশা করি মসি পাবুংদি", "হে অল্লাহ, মসি ঐহাক্না পাম্লিবা অদোম্না পীবা থৌজালনি, মরম অদুনা ঐহাক্না মমিৎ কুপ্লবা ফাওবা ঐ মশামক্তা থাদোক্তবা য়াদে, অমসুং ঐগী থবক পুম্নমক অমুক হন্না তৌহনগনু। অদোম্না নত্তনা লাইরেম্বী অমত্তা লৈতে।", "দি দুয়া অফ দি ওয়ান ইন ডিসট্রেস (দা'ৱাত অল-মক্রুব)।", "মসি লাইরেম্বীনা লাইরেম্বীগী লাইরেম্বীনি হায়না কৌখি।"),
        "dua_against_enemy_ahzab" to DuaText("য়েক্নবশিংগী লান্মীশিংগী মায়োক্তা লৈবা", "হে অল্লাহ, লাইরিক অসিবু ফোংলিবা, য়াম্না থুনা মশীং থিগৎপা! কনফেডেরেতশিংবু মাইথিবা পী। হে অল্লাহ, মখোয়বু মাইথিবা পীয়ু অমসুং মাংহল্লু।", "য়েক্নবশিংগী মাইয়োক্তা-কনফেদরেতশিংগী লানগী দুআ।", "মসি লাইরেম্বীনা ইৎথ্নোগ্রফিগী লমদা ইৎথ্নোগ্রফিগী লমদা য়াম্না মরু ওই।"),
        "dua_anta_adudi" to DuaText("অদোম্না ঐগী খোঙফম চেৎকনি", "হে অল্লাহ, অদোম্না ঐগী মতেং পাংবী অমসুং ঐগী মতেং পাংবীনি। ঐহাক্না অদোম্না থৌরাং তৌরি, অদোম্না ঐহাক্না খুমাং চাউশিল্লক্লি অমসুং অদোম্না ঐহাক্না লান শোক্লি।", "অচৌবা শিংনবশিং অমা নৎত্রগা চাংদম্নবা অমা লৈদ্রিঙৈদা।", "মসি প্রোপেক্ত সলিহ আলীহ ওসল্মনা লানদা হায়খি।"),
        "dua_ikfinihim" to DuaText("মখোয়গা মখোয়গা মরুপ মপাং ওইবা অসি অফবা অমনি", "হে আল্লাহ, ঐহাক্না মখোয়গী মাইয়োক্তা মতীক চারগনি, মসি মখোয়না পাম্লবসু ওইগনি।", "অপ্রেসরশিংগী ফত্তবা অদুগী মায়োক্তা-দিচ ওফ দিচকী মীওই অমগী ৱারীদা অঙাং অদুগী দুআ।", "আল্লাহনা অঙাং অদুবু অৱাবা পীবদগী ঙাকথোক্লম্মী।"),
        "dua_qadarullah" to DuaText("করিগুম্বা ফত্তবা থৌদোক অমা থোকপা তারবদি।", "মসি অল্লাহগী য়াথংনি অমসুং মহাক্না তৌখিবাশিংদু লানখ্রে।", "করিগুম্বা ফত্তবা থৌদোক অমা থোকপা মতমদা,'করিগুম্বা অমখক্তমক'হায়বগী মহুত্তা।", "'করিগুম্বা অমত্তা ওইদ্রবদি'না শায়তনগী থোঙ হাংই।"),
        "dua_ala_kulli_hal" to DuaText("ফিভম খুদিংমক্তা চাউথোকচবা পোকচরি", "ফিভম খুদিংমক্তা ঈশ্বরবু থাগৎলি।", "করিগুম্বা অমনা নাপাক পোকখ্রবদি।", "মসি মহাক্না পামদবা অমা থেংনবদা প্রধান মন্ত্রী মোদীনা হায়খি।"),
        "dua_dogs_barking" to DuaText("নুংথিলগী মতমদা ঙানুগী খোঞ্জেল তাবা", "ঐনা শাপিত শয়তানদগী অল্লাহদা শরণ লৈ।", "নুংথিলগী মতমদা শঙ্গোমশিংনা ৱা ঙাংগনি নত্ত্রগা খোম্লাং অমা ঙাংগনি।", "করি ওইরকপা হায়বদু য়েংবদা তাবনি হৌজিক।"),
        "dua_leaving_home_adilla" to DuaText("লমহাংদগী লাকপা মীরোল্লিবা", "হে অল্লাহ, ঐহাক্না ইশাবু পুকচেল শেংবা নৎত্রগা ৱাখল মাংহন্দবা, ঐহাক্না তৌগদবদু নৎত্রগা তৌগদবদু, ঐহাক্না তৌগদবদু নৎত্রগা তৌদবনা, ঐহাক্না তৌগদবদু নৎত্রগা তৌদবনা, ঐহাক্না তৌগদবদু নৎত্রগা তৌদবনা তৌদবনা, ঐহাক্না তৌগদবদুবু পুকচেল শেংবা নৎত্রগা তৌদবনা তৌদনা, ঐহাক্না থৌদোক্তবা নত্ত্রগা থৌদোক্তবা ওইদনা, ঐহাক্না থৌদোক্তবা নত্ত্রগা থৌদোক্তবা ওইদনা, ঐহাক্না থৌদোক্তবা নত্ত্রগা থৌদোক্তবা ওইদনা, ঐহাক্না থৌদোক্তবা নত্ত্রগা থৌদোক্তবা ওইদনা, ঐহাক্না থৌদোক্তবা নত্ত্রগা থৌদোক্তবা ওইদনা, ঐহাক্না থৌদোক্তবা নত্ত্রগা থৌদোক্তবা ওইদনা, ঐহাক্না থৌদোক্তবা নত্ত্রগা থৌদোক্তবা ওইদনা লৈহনগনু।", "য়ুম থাদোরকপা মতমদা-উম্ম সলামাহ (আর. এ.) না ৱারী শাখি।", "মসি মহাক্না মহাক্কী য়ুমদগী মপান্দা চৎলুরবা মতম খুদিংদা ইখি।"),
        "dua_ascending_descending" to DuaText("চৎখি অসুম অসুম", "আল্লাহ অসি খ্বাইদগী চাওবা (ৱাংখৎলকপা মতমদা) নি।-(ৱাংখৎলকপা মতমদা) আল্লাহবু ইকায় খুম্নজরি।", "লমকোয়বা অমদা, মথক্তা চৎপা মতমদা'আল্লাহু অকবর'অমসুং মখাদা লাকপা মতমদা'সুভানাল্লাহ'হায়য়ু।", "লমকোয়বা মতমদা কম্পেনিয়নশিংগী (আর. এ.) প্রেক্তিস।"),
        "dua_traveller_sahar" to DuaText("অয়ুক পুং তারকপদা লমকোয়বা লাকপা নুপিশিংগী ওইবা", "ঐখোয়না অল্লাহবু থাগৎলি অমসুং মহাক্কী থৌজালশিং অদু ঐখোয়না ফংহনলি। হে ঐখোয়গী ইশ্বর, ঐখোয়গী খোঙশানবা তৌ অদুগা ঐখোয়গী থৌজাল অদু থৌশাবীদুনা, মৈদগী ঙাকথোক্নবা, (ঐহাক্না মসি হায়জরি)।", "অয়ুক পুংশিল্লকপদা, নোংঙাল্লগা চৎলগা।", "মসি প্রোফেট সলিহ আলীহ ওসল্মনা চৎপদা অয়ুক পুং পুংফমগী মমাংদা হায়খি।"),
        "dua_zawwadakallah" to DuaText("লমকোয়বাশিংদাঃ অল্লাহনা তক্ৱা পীবা য়াই।", "অল্লাহনা নংনা চৎপা চৎনবগীদমক তাকৱা পীবা, নংনা তৌখ্রবা পাপশিং অদু মাংহনবা অমসুং নংনা লৈরিবা মফম অমহেক্তদা নংনা হেন্না ফবা ওইহনগনু।", "লমকোয়বা মীওই অমদা থৌগল তৌব মতমদা।", "মসি মহাক মশাগী ৱাখল্লোনগী মতুং ইন্না মহাক্না মহাক্কী ৱাখল্লোন অদু ফোংদোক্নবগীদমক মহাক্না মহাক্কী ৱাখল্লোন অদু ফোংদোক্নখি।"),
        "dua_traveller_to_resident" to DuaText("লমকোয়বা লাকপা মীওইশিং", "ঐহাক্না থাজবা মাঙদবা, থাজবা মাঙদবা, অল্লাহদা থাজবা থম্লি।", "ইমুং মনুংবু নীংশিংগদবা মতমদা লমকোয়বশিংনা হায়খি।", "ইমুং-মনুং পুনশীন্দুনা থম্নবা হোৎনরিবা অদু অল্লাহদা পীরম্মী।"),
        "dua_entering_village" to DuaText("খুঙ্গং অমা নৎত্রগা সহর অমা হেক্তগী ওইনা,", "হে আকাশ তরেৎকী অমসুং মখোয়না লৈজবা মচুশিংগী, পৃথিবী তরেৎকী অমসুং মখোয়না পুশিল্লিবা পুম্নমক্কী, শয়তানশিংগী অমসুং মখোয়না লান্না চৎলিবা পুম্নমক্কী, নুংশিৎকী অমসুং মখোয়না শন্দোক-পুশিল্লিবশিংগী, ঈশিংগী অমসুং মখোয়না থোকহনবা পুম্নমক্কী, ঈশিংগী, অমসুং ঐখোয়না সহর অসিগী অফবা অমসুং মসিগী মীয়ামগী অফবা অদু পামজৈ। অমসুং ঐখোয়না মসিগী ফত্তবা, মসিগী মীয়ামগী ফত্তবা অমসুং মসিগী মনুংদা লৈরিবা ফত্তবা অদুগীদমক নংগী মফমদা শরণ লৈ।", "শহর নত্ত্রগা সহরগী তোখাইবা মখাদা পীরে।", "মসি মহাক্না সহর অমদা চংনবা পাম্লকপা মতম খুদিংদা ইখি।"),
        "dua_vehicle_stumbles" to DuaText("গাড়ীদু নুংশিনবা মতমদা", "মসি ঈশ্বরগী মমিংনি।", "'মে শায়তন পেরিস'হায়না হায়বগী মহুত্তা, মাউন্ত নত্ত্রগা ভেহিকল অদুনা লেংবা নত্ত্রগা লেংবা মতমদা।", "বিস্মিল্লাহ হায়রম্বনা শায়তনবু উচেক অমগী চাউবদা হন্থহল্লি।"),
        "dua_ajz_kasal_haram" to DuaText("অহল ওইরবা মীওইশিং অমসুং অহল ওইরবা মীওইশিং", "হে অল্লাহ, ঐহাক্না নুংশিবা অমসুং অলসতা, কা হেন্না শাৎপা অমসুং অহল ওইবদগী, পুন্সি অমসুং শিবগী চাংয়েংশিংদগী, অমসুং কবরগী লাইয়েংগী লাইয়েংগী মতেং লৌদুনা ঐনা তুম্বুদা শরণ লৈ।", "নুংতিগী ওইবা মপুং ওইবা শেলথুমগী ওইবা নুংতিগী ওইবা দোৱা অমা।", "মসি অখঙ-অহৈশিংনা তোইনা ইনরম্মি।"),
        "dua_sharri_ma_amiltu" to DuaText("ঐগী থবকশিংগী মখোঙদগী ঙাকথোক্নবা", "হে আল্লাহ, ঐহাক্না তৌখ্রবা ফত্তবা থবকশিংদগী অমদি তৌদদ্রবা ফত্তবা থবকশিংদগী ঐহাক্না তুম্বুগী মফমদা পুকনিংলি।", "আয়েশা (রা.) গী মতুং ইন্না, মসি প্রোফেট (সা.) গী দুআ অমনি।", "করি তৌখিবনো অমসুং করি তৌদবনো হায়বগী ফলশিংদগী ঙাকথোক্নবা।"),
        "dua_jahdil_bala" to DuaText("শাথীনা য়েংশিনবা য়াবা রিহেবিলিটেসন", "হে অল্লাহ, ঐহাক্না তুম্বুবু য়াম্না লুবা চাংয়েংদগী, অৱাবা তারবদগী, ফত্তবা ৱায়েলদগী অমসুং য়েক্নবশিংবু পুকচেল শেংবদগী ঙাকথোক্নবা হোৎনৈ।", "শাথীনা থেংনরিবা চাংয়েংশিংদগী ঙাকথোক্নবা অমসুং য়েক্নবশিংবু পুকচেল শেংবা।", "প্রধান মন্ত্রী মোদীগী হৌদোক ৱারোলদা প্রধান মন্ত্রী মোদীগী ৱারোলগী মতাংদা ৱা ঙাংখ্রে।"),
        "dua_fitnat_ghina_faqr" to DuaText("শেল-থুম অমসুং লাইরবা লৈবগী চাংয়েংশিংদগী ঙাকথোকপা", "হে অল্লাহ, ঐহাক্না তুম্বুবু অলসতা অমসুং অহল ওইবদগী, পাপ অমসুং শেন্দোংদগী, কবরগী চাংয়েং অমসুং লাইয়েংগী, মৈগী চাংয়েং অমসুং লাইয়েংগী, লন থুমগী চাংয়েং অমসুং লাইরবা চাংয়েংদগী ঙাকথোক্নবা হোৎনৈ।", "কবর, নরক, লন-থুম অমসুং লাইরবা (দুআগী শরুক) গী চাংয়েংশিংদগী রিফুজ তৌ।", "মসি লাইরেম্বী সল্লল্লাহু অলৈহি ঵সল্লমগী পুকচেল শেংলবা লাইরেম্বী অমনি।"),
        "dua_kufr_faqr" to DuaText("লাই য়েকপা অমসুং লাই য়েকপা", "হে অল্লাহ, ঐহাক্না থাজদবা অমসুং লাইরবা অসিদগী নংনা শরণ লৈ, অমসুং কল্লবা লাইফমদগী নংনা শরণ লৈ। নংখক্তনা লাইরেম্বী অমত্তা লৈতে।", "হৌখিবা হপ্তা অনী।", "আবু বকরাহ (রা.) না মসি পৈগম্বর সল্লল্লাহু অলৈহি ঵স্লমনা হায়রম্বদু ৱাৎখি।"),
        "dua_sharri_sami" to DuaText("মাই সেন্সসকী ফত্তবা ৱাফমদগী ঙাকথোকপা", "হে আল্লাহ, ঐনা ঐগী ৱা ঙাংবা, ঐনা উবা, ঐগী লোলগী ফত্তবা, ঐগী নুংশিৎকী ফত্তবা অমসুং ঐগী অপাম্বগী ফত্তবা অসিদগী ঐহাক্না নোংখৌ ঙাকথোক্নবা হোৎনৈ।", "শকল ইবন হুমাইদ (আর. এ.) দা তম্বিয়ু।", "মশা-মশানা মশাবু পাপতগী ঙাক-শেন্নবগীদমক খুৎশা-খুৎলাইশিং অমসুং খুদম্বু ঙাক-শেন্নবগীদমক দুআ অমা।"),
        "dua_hadm_gharaq" to DuaText("খঙহৌদনা শিখিবা অমসুং খুদোংথিবা থোকপদগী ঙাকথোকপা", "হে অল্লাহ, ঐহাক্না (বিলদিং অমনা) লুখ্রাবীদগী, অৱাংবা মফম অমদগী, ঈশিং কুপ্লবা, মৈ চাকপা অমসুং অহল ওইবদগী; শায়তানদগী, শায়তনা মরম ওইদুনা, লম্বীদগী লাপথোক্তুনা, অমসুং (ভেনোমস) স্তিং অমনা মরম ওইদুনা, ঐদগী ঙাকথোক্নবা হোৎনৈ।", "খুদোংথিবা অমসুং ফত্তবা পুন্সিদগী ঙাকথোক্নবগীদমক।", "মসি লাইরেম্বী সল্লল্লাহু অলৈহি ঵সল্লমগী নীংতম্বা লাইরেম্বীনি।"),
        "dua_ju_khiyanah" to DuaText("অৱাবা অমসুং অৱাবা নংবা", "হে অল্লাহ, ঐহাক্না য়ুবু চানবিবদগী ঙাকথোক্নবা হোৎনৈ, মরমদি মসি ফত্তবা মরুপ অমনি, অমসুং ঐহাক্না য়ুবু নীংথিজদবা অসিদগী ঙাকথোক্নবা হোৎনৈ, মরমদি মসি ফত্তবা থাজবা লৈবা অমনি।", "অৱাবা অমসুং অৱাবা নংবদগী ঙাকথোক্নবা হোৎনৌ।", "মসি লাইরেম্বী সল্লল্লাহু অলৈহি ঵সল্লমগী নীংতম্বা লাইরেম্বীনি।"),
        "dua_huda_tuqa" to DuaText("লাই য়েকপা, লাই য়েকপা, লাই য়েকপা অমসুং মতিক চাবা", "হে আল্লাহ, ঐহাক্না থৌশিল পীবা, অচুম্বা, শেংলবা অমসুং মশা-মউ ফবা লৈহন্নবা হায়জরি।", "মসি লাইরেম্বী সল্লল্লাহু অলৈহি ঵সল্লমগী অশেংবা লাইরেম্বী অমনি।", "ধর্ম অমসুং মালেম অসিগী য়ুম্ফম ওইবা থৌজাল মরি।"),
        "dua_aslih_li_dini" to DuaText("ঐগী ধর্ম, মালেম অমসুং মসিগী তুংদা লৈরিবা অসি শেমদোক-শাদোকউ।", "হে অল্লাহ, ঐগী থবক থৌরম খুদিংমক ঙাক শেনবা, ঐগী ধর্মবু চপ চানা তৌ; ঐগী পুন্সিবু চপ চানা শেম্মু, মসিদা ঐগী পুন্সি হিংলি; অমসুং ঐ হল্লকপা তুংদা অমুক হন্না লৈয়ু। অফবা খুদিংমক অসিদা ঐগী পুন্সি অসি হেন্না হেনগৎহনবিয়ু, অমসুং ফত্তবা খুদিংমকদগী শিববু নুংঙাইহনবিয়ু।", "ধর্ম, মালেম অমসুং অকোনবা-অহুম অসি নৌনা শেমগৎপা।", "মসি লাইরেম্বী সল্লল্লাহু অলৈহি ঵সল্লমগী মপুং ওইবা ৱারোলনি।"),
        "dua_musarrifal_qulub" to DuaText("ঐখোয়গী থৱায়শিংবু ঐখোয়গী থৌজালদা ওনবা", "হে আল্লাহ, নুংশিৎ তানবা, ঐখোয়গী থৱায়বু নংনা তৌবীমল খঙবা ঙমহনবীরি।", "হৃদয়কে দৃঢ়ভাবে মেনে চলার জন্য একটি ডুয়া।", "মীওই খুদিংমক্কী থৱায়শিং অসি খ্বাইদগী করুণাময়ী মীওই অমগী খুবাক অনীগী মরক্তা লৈ।"),
        "dua_jannah_nar" to DuaText("জান্নাহ, মৈগী রিফুজি", "হে আল্লাহ, ঐহাক্না নোংখৌ স্বর্গগীদমক হায়জরি অমসুং মৈদগী ঐহাক্না নোংখৌ শরণ পী।", "তাশাহুদকী মতুংদা নত্ত্রগা মতম অমহেক্তদা।", "প্রধান মন্ত্রী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, অমসুং শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী, শ্রী নরেন্দ্র মোদী,"),
        "dua_khayri_kullih" to DuaText("হৌজিক অমসুং মসিগী মতুংদা অমুক থোকখিবা মীশিংগী মরত্ত া অফবা হায়বদুনি।", "হে অল্লাহ, ঐহাক্না তুম্বু অফবা পুম্নমক-থুনা অমসুং মাং তাকপশিং, ঐহাক্না খঙলিবা অমসুং খঙবা ঙমদবা পুম্নমক-অমসুং ঐহাক্না ফত্তবা পুম্নমক-থুনা অমসুং মাং তাকপশিং, ঐহাক্না খঙলিবা অমসুং খঙবা ঙমদবা পুম্নমক-অসিদগী ঐহাক্না তুম্বু শরণ পী। হে অল্লাহ, ঐহাক্না ময়ামবু স্বর্গ অমসুং ৱাহৈ অমসুং থবকশিংনা ঐঙোন্দা মসিগী নকশিন্নবগীদমক অমসুং ঐহাক্না মৈদগী অমসুং ৱাহৈ অমসুং থবকশিংনা ঐঙোন্দা নকশিন্নবদগী ঐহাক্না তুম্বু শরণ পী।", "মসি অখঙ-অহৈশিংনা ইৎথ্নোগ্রফরশিংগী মফমদা ইৎথ্নোগ্রফরশিংগী মরক্তা ৱারী শানবগী মওং মতৌগী মতাংদা নৈনখি।", "অফবা খুদিংমক খোমজিল্লিবা দুআ অমা।"),
        "dua_ihdini_saddidni" to DuaText("ঐগা খোঙশানবা অমসুং মাংজিল থাদুনা লৈয়ু", "হে আল্লাহ, অদোম্না ঐঙোন্দা অচুম্বা লম্বী পীয়ু।", "মসি নবী সল্লল্লাহু অলৈহি ঵স্লমনা অলি (রা.) দা তাক্লম্মী।", "লম্বী অমদা চৎলিবা থৌশিল অমা ওইনা অমসুং সাদ্দা অসি তীরগী থোংবা থৌশিল অমা ওইনা য়েংউ।"),
        "dua_hubbaka" to DuaText("ঈশ্বরগী নীংশীংবু নুংশিবা", "হে অল্লাহ, ঐহাক্না নোংখৌ নুংশিজবা, নোংখৌ নুংশিজবা মীওইশিংগী নুংশিজবা, অমসুং ঐহাক্না মাগী নুংশিৎতা পুশিল্লিবা থবকশিংগীদমক হায়জরি। হে অল্লাহ, ঐগী, ঐগী ইমুং-মনুং অমসুং অইংবা ঈশিংদগী হেন্না ঐগী নুংশিৎপু হেন্না নুংশিজবা ওইহনবি।", "দাউদ (এ. এস.) গী দুআ অসি প্রোফেট সলিহ আলীহ ওস্লমনা মরী লৈনৈ।", "ঈশ্বরবু নুংশিবা হায়বসি খ্বাইদগী ফবা আর্বিট্রেটর অমনি।"),
        "dua_filal_khayrat" to DuaText("অফবা অমসুং ফত্তবা পোৎ-চৈশীং পীবা", "হে অল্লাহ, ঐহাক্না নুংশিবা পামজৈ মদুদি ঐহাক্না অফবা থবক তৌবা ঙমহন্নবা, ফত্তবা থবকশিং থাদোকপা অমসুং লাইরবা মীওইশিংবু নুংশিনবা, অমসুং অদোম্না ঐঙোন্দা ক্ষমা তৌহন্নবা অমসুং ঐঙোন্দা থৌজাল পীবা। অমসুং করিগুম্বা অদোম্না মীওই অমগীদমক চাংয়েং তৌনবগীদমক খল্লবদি, চাংয়েং তৌদনা ঐঙোন্দা পুদুনা লৈয়ু। ঐহাক্না অদোমগী নুংশিজবা, মহাকপু নুংশিজবা মীওইশিংবু নুংশিজবা, অমসুং ঐহাক্না মহাক্কী নুংশিৎকী মনাক্তা পুরক্লিবা থবকশিংদা নুংশিজবা পামনবা পামজৈ।", "আল্লাহনা মসি দোৱা অসি ফুরুপ অমদা পৈগম্বর সল্লল্লাহু অলৈহি ঵স্লমদা তাক্লম্মী।", "মসি তশেংবনি, মরম অসিনা মসিবু তমথীয়ু অমসুং মসিবু তমথীয়ু হায়না প্রোপেৎ সল্লল্লাহ অলিয়া ওসল্মনা হায়খি।"),
        "dua_bi_ilmikal_ghayb" to DuaText("পুন্সি অসি অফবা হায়বদু ওইদ্রিবা মতমদসু হিংবা য়াহল্লু।", "হে অল্লাহ, অদোম্না উবা ঙমদবগী মরমদা খঙলবা অমসুং সৃষ্টির মথক্তা লৈবা শক্তিনা-পুন্সি অসি ঐগীদমক্ত হেন্না অফবা হায়বদু খঙদ্রিবা মতম ফাওবা ঐঙোন্দা হিংবা য়াহল্লু, অমসুং শিবনা ঐহাক হেন্না ফবা হায়বদু খঙলবা মতম ফাওবদা ঐহাকবু পুদুনা চৎলু। হে অল্লাহ, ঐহাক্না নোংখৌ অরানবনি অমসুং মীয়ামদা, নুংঙাইবা অমসুং কোপদা অচুম্বা ৱাহৈ, অমসুং লাইরবা অমসুং লন থুমদা মিতরেসন তৌনবগীদমক হায়জরি।", "অম্মার ইবন ইয়াসির (আর. এ.) গী লাই খোইরম্বা দুআ (হৌদোকপগী শরুক)।", "মসি লাই খোইরম্বদা প্রধান মন্ত্রী শ্রী নরেন্দ্র মোদীনা হায়খি।"),
        "dua_ism_azam_mannan" to DuaText("ইসম-ই-আজমঃ অল-মন্নান", "হে অল্লাহ, ঐহাক্না নোংখৌ হায়জরি মদুদি পুকচেল শেংবা পুম্নমক অসি তুং অসিনি। নুংখক্তা নত্তনা লাইরেম্বী অমত্তা লৈতে, থৌজাল পীবা, স্বর্গ অমসুং পৃথীবিগী হৌরকফম। হে ইকায় খুম্নজবা অমসুং ইকায় খুম্নজবা, হে মতম চুপ্পদা হিংবা ঙম্বা, হে তুংলমচৎ ঙাকপা!", "প্রফেট সলিহ আলীহ ওসল্মনা হায়খি মদুদি মীওই অসিনা অল্লাহগী খ্বাইদগী চাউবা মমিংনা দুআ শেম্মী।", "মমিং অসিনা মমিং লৈরবা দুৱা অমগী পাউখুম পীরি।"),
        "dua_ism_azam_ahad_samad" to DuaText("ইসম-ই-আজমঃ অল-অহদ আস-সমদ", "হে অল্লাহ, ঐহাক্না নোংখৌ হায়জরি, মরমদি ঐহাক্না মসি উৎলে মদুদি অদোম্না অল্লাহনি; অদোম্না নত্তনা, অমত্তা, মশা-মউ ফবা, পোক্তবা নত্ত্রগা পোক্তবা, অমসুং মহাকগা চাংদম্নবা য়াবা অমত্তা লৈতবা, লাইরেম্বী অমত্তা লৈতে।", "মহাক্না হায়খি মদুদি মীওই অসিনা মহাক্কী খ্বাইদগী চাউবা মমিংনা অল্লাহদা হংলম্মি।", "মহাক্না হায়,'মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়,'মহাক্না হায়, মহাক্না হায়, মহাক্না হায়,'মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়,'মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়,'মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়, মহাক্না হায়।"),
        "dua_thabbitni_hadiyan" to DuaText("আমাকে অফবা, অফবা অমসুং অফবা পুরিনবা", "হে অল্লাহ, ঐঙোন্দা থাজবা অমা থম্মু, অমসুং ঐহাক্না থৌশিল পীবা অমসুং থৌশিল পীবা মীওই অমা ওইয়ু।", "প্রফেট সলিহ আলীহ ওস্লমনা হায়রিবা দুআ অসি জারির (আর. এ.) গীদমক শেমখি (মশানা'থাবিতনি'হায়নবা)।", "জারির (আর. এ.) গী অশেংবা দুআ অসিনা'থাবিত-হু'হায়বা ৱাহৈশিং শীজিন্নৈ।"),
        "dua_rabbighfir_tub_alayya" to DuaText("ঐনা ঐগী ওজাশিংবু নমথাক তৌরম্বা অমসুং ইকায় খুম্নবা উৎচরি।", "হে ঐগী ইশ্বর, ঐঙোন্দা তৌবীমল খঙবা অমসুং ঐনা তৌবীমল খঙবা অদু লৌয়ু। তশেংনমক্কী, অদোম্না তৌবীমল খঙবা ঙম্বা, থৌজাল পীবা মীওইনি।", "চপ মান্নবা সিতিং অমদা চামা হেনবগী থৌওং-মসি প্রোফেত সল্লল্লাহু অলৈহি ঵স্লমগী চৎনবীনি।", "কম্পেনিয়নশিংনা মসি চপ চাবা মতমদা নপুংসল্লাহুনা চামাথোই হেন্না হায়রম্বা অদু মশীং থীখি।"),
        "dua_rafiq_ala" to DuaText("লৈখিদ্রবশিংগী মনুংদা", "হে আল্লাহ, ঐঙোন্দা ইরাং তৌ, ঐঙোন্দা ইরাং তৌ অমসুং খ্বাইদগী ৱাংবা কম্পানিয়নগা লোয়ননা য়াওয়ু।", "মসি লাইরেম্বীনা মশাগী ৱাখল্লোন্দা ইবদা লাইরেম্বীনা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা ইবদা", "মহাক্না লৈখিদবদা প্রধান মন্ত্রী মোদীগী মফমদা ইকাই খুম্নবা উৎচরি।"),
        "dua_la_bas_tahur" to DuaText("অসুস্থদের সান্ত্বনা দেওয়াঃ পিউরিফিকেশন", "করিগুম্বা অল্লাহনা পাম্লবদি মসি (পাপশিংদগী) প্যুরিফিকেসন অমনি।", "চৎপদা লাকপা মতমদা লায়না লৈবা মীওইবু নুংঙাইহনবা।", "মসি লাইরেম্বী সল্লল্লাহু অলৈহি ঵সল্লমনা লায়না অসি থেংনরিবা মতমদা হায়খি।"),
        "dua_talqeen" to DuaText("তিলকিনা", "অচুম্বা থৌওংনি হায়বদি, অচুম্বা থৌওংনি হায়বদি, অচুম্বা থৌওংনি।", "মরি লৈনবা মীওই অমগী মনাক্তা কলিমা অসি ইবীয়ু (মসিবু হায়রক্নবা মখোয়বু থৱায় য়াওহল্লোই)।", "'লা ইলাহা ইল্লাল্লাহ'হায়বসি মহাক্কী অরোইবা ৱাহৈ অমা ওইবা মীওই অদু পেরেদাইজতা চঙগনি (অবু দাউদ 3116)।"),
        "dua_ahyini_ma_kanat" to DuaText("শিরবা মতুংদদি মসিদা অৱাবা লৈতে।", "হে আল্লাহ, পুন্সিনা হেন্না ফবা মতম ফাওবদা ঐহাক হিংবা ঙম্লু, অমসুং শিবনা হেন্না ফবা মতম ফাওবদা ঐহাক লৈয়ু।", "অৱাবা তারকপদা শিবগী মহুত্তা।", "প্রফেট সলিহ আলীহ ওসল্মনা শিরবা পামদবা য়াহন্দে অমসুং মদুগী মহুত্তা মসিবু তাক্লম্মী।"),
        "dua_for_one_i_cursed" to DuaText("ঐনা ৱাহৈ পরেং ওইনা ঙাংবা মীওই অমগীদমক", "হে অল্লাহ, ঐহাক্না নীংথিজদবা থাজরিবা মীওই অমহেক্তবু, অমুক হল্লকপা নুমিত্তা মহাক্কীদমক মসি নক্ননবগী পাম্বৈ অমা ওইহনবিয়ু।", "করিগুম্বা মীওই অমনা মহাকগা নুংশিনবা মতমদা য়াম্না শাওখি।", "মসি লাইরেম্বী সল্লল্লাহু অলৈহি ঵সল্লমগী লাইরেম্বীনি।"),
